import { Metadata } from "next";
import Link from "next/link";
import PNRClient from "./PNRClient";

const CANONICAL = "https://www.trayago.in/pnr";

// 1. Technical SEO Metadata for PNR Portal
export const metadata: Metadata = {
  title: "PNR Status Check & Prediction | Trayago",
  description:
    "Check railway PNR status online with Trayago. Enter your 10-digit PNR number to see current booking status, waitlist position, chart preparation, and an AI confirmation probability estimate.",
  alternates: {
    canonical: CANONICAL,
  },
  keywords:
    "PNR status, PNR status check, PNR status check online, railway PNR status, train PNR status, PNR prediction, PNR confirmation probability, train ticket status",
  robots: {
    index: true,
    follow: true,
  },
  openGraph: {
    type: "website",
    title: "PNR Status Check & Prediction | Trayago",
    description:
      "Check railway PNR status online with Trayago. Enter your 10-digit PNR number to see current booking status, waitlist position, and AI confirmation probability estimate.",
    url: CANONICAL,
    siteName: "Trayago",
    images: [{ url: "/og-image.png", width: 1200, height: 630, alt: "Trayago PNR Status" }],
  },
  twitter: {
    card: "summary_large_image",
    title: "PNR Status Check & Prediction | Trayago",
    description:
      "Check railway PNR status online with Trayago. Enter your 10-digit PNR number to see current booking status, waitlist position, and AI confirmation probability estimate.",
    images: ["/og-image.png"],
  },
};

// 2. Single source of truth for FAQ — rendered visibly AND as FAQPage JSON-LD
const PNR_FAQS: { q: string; a: string }[] = [
  {
    q: "What is PNR status?",
    a: "PNR status is the current booking state of a railway ticket, identified by a 10-digit PNR number printed on the ticket or sent in the booking confirmation. It shows whether each passenger is confirmed, in RAC, or still on the waitlist, along with coach and berth details once they are allotted.",
  },
  {
    q: "How do I check my PNR status on Trayago?",
    a: "Enter your 10-digit PNR number in the field at the top of this page and select Check Status. Trayago retrieves the latest booking status for that PNR and displays passenger-wise details, chart preparation state, and a confirmation probability estimate where one can be computed. No account or login is required, and checking PNR status is free.",
  },
  {
    q: "What does CNF mean on a PNR status?",
    a: "CNF means confirmed. The passenger has a reserved berth or seat for the journey. Once the reservation chart is prepared, the coach and berth number are shown alongside the CNF status.",
  },
  {
    q: "What does RAC mean on a PNR status?",
    a: "RAC stands for Reservation Against Cancellation. An RAC passenger may board the train and is allotted a shared side-lower berth, typically with two passengers sharing one berth. RAC tickets can move to confirmed if berths become free before or after chart preparation.",
  },
  {
    q: "What does WL mean on a PNR status?",
    a: "WL means waitlist. The ticket has no berth allotted yet and its position in the queue is shown as a number, for example GNWL 12 or PQWL 5. Waitlisted tickets move up as other passengers cancel. A ticket that is still waitlisted after the final chart is prepared is generally not valid for travel in a reserved coach.",
  },
  {
    q: "What is chart preparation?",
    a: "Chart preparation is the point at which Indian Railways finalises berth allocation for a train, usually a few hours before departure. Trayago shows whether the chart is prepared for your PNR, because status changes are far more likely before this point than after it.",
  },
  {
    q: "Can my PNR status change after booking?",
    a: "Yes. A waitlisted or RAC ticket can move towards confirmation as other passengers cancel, and berth or coach allocation can change when the chart is prepared. Checking your PNR status again closer to departure is the reliable way to see the current position.",
  },
  {
    q: "How does Trayago's PNR confirmation prediction work?",
    a: "Trayago compares your current waitlist position against historical booking and cancellation trends for the same train, class, quota, and route, along with factors such as travel date and seasonality. The result is expressed as a confirmation probability. It is a statistical estimate, not a decision by Indian Railways, and unusual demand or last-minute changes can make the actual outcome differ.",
  },
  {
    q: "Does Trayago guarantee confirmed tickets?",
    a: "No. Trayago provides journey intelligence, status information, and probability estimates to help you plan. Only Indian Railways allots berths, and no confirmation can be guaranteed by Trayago.",
  },
  {
    q: "Is Trayago affiliated with IRCTC?",
    a: "No. Trayago is an independent travel intelligence platform and is not affiliated with, endorsed by, or operated by IRCTC or Indian Railways. Ticket booking is completed through official booking platforms.",
  },
];

export default function PNRPage() {
  // 3. Structured Data Schemas
  const breadcrumbSchema = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      {
        "@type": "ListItem",
        position: 1,
        name: "Home",
        item: "https://www.trayago.in",
      },
      {
        "@type": "ListItem",
        position: 2,
        name: "PNR Status",
        item: CANONICAL,
      },
    ],
  };

  const faqSchema = {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: PNR_FAQS.map(({ q, a }) => ({
      "@type": "Question",
      name: q,
      acceptedAnswer: {
        "@type": "Answer",
        text: a,
      },
    })),
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbSchema) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(faqSchema) }}
      />
      <PNRClient />

      {/* Explanatory SEO content — rendered below the tool so the PNR check stays above the fold */}
      <section
        aria-labelledby="pnr-guide-heading"
        className="w-full px-4 md:px-8 pb-16"
      >
        <div className="max-w-4xl mx-auto w-full border-t border-strong pt-12 space-y-10 text-sm text-secondary leading-relaxed">
          <div className="space-y-4">
            <h2
              id="pnr-guide-heading"
              className="text-xl font-black text-main"
            >
              PNR Status Check &amp; Confirmation Prediction
            </h2>
            <p>
              Every reserved Indian Railways ticket carries a 10-digit{" "}
              <strong>PNR number</strong> that records who is travelling, on
              which train, and in which class. Checking the{" "}
              <strong>PNR status</strong> tells you the current booking status
              for each passenger on that ticket — confirmed, RAC, or still
              waitlisted — plus coach and berth details once they have been
              allotted.
            </p>
            <p>
              Trayago reads the latest status for your PNR and, where a
              waitlist position exists, adds a{" "}
              <strong>PNR confirmation probability</strong> estimate derived
              from historical booking and cancellation patterns. The estimate is
              a statistical projection to help you plan — it is not a decision
              by Indian Railways, and confirmation cannot be guaranteed.
            </p>
          </div>

          <div className="space-y-3">
            <h3 className="text-base font-bold text-main">
              How to check PNR status online
            </h3>
            <ol className="list-decimal pl-5 space-y-2">
              <li>
                Enter the 10-digit PNR number from your ticket in the field at
                the top of this page.
              </li>
              <li>
                Select <strong>Check Status</strong>. Trayago fetches the
                current <strong>train ticket status</strong> for that booking.
              </li>
              <li>
                Review the passenger-wise booking status, chart preparation
                state, and the confirmation probability estimate where one is
                available.
              </li>
            </ol>
            <p>
              No account and no IRCTC login is needed, and checking{" "}
              <strong>railway PNR status</strong> on Trayago is free.
            </p>
          </div>

          <div className="space-y-3">
            <h3 className="text-base font-bold text-main">
              Understanding CNF, RAC and WL
            </h3>
            <ul className="space-y-2 pl-5 list-disc">
              <li>
                <strong>CNF</strong> — Confirmed. A berth or seat is reserved
                for the passenger. Coach and berth numbers appear once the
                reservation chart is prepared.
              </li>
              <li>
                <strong>RAC</strong> — Reservation Against Cancellation. The
                passenger may board and is allotted a shared side berth. RAC can
                move to confirmed if berths free up.
              </li>
              <li>
                <strong>WL</strong> — Waitlist. No berth is allotted yet; the
                queue position is shown as a number, such as GNWL 12 or PQWL 5.
                A ticket still on the <strong>waitlist</strong> after the final
                chart is generally not valid for travel in a reserved coach.
              </li>
            </ul>
            <p>
              <strong>Chart preparation</strong> usually happens a few hours
              before departure and is the point at which berth allocation is
              finalised. Status movement is far more likely before the chart is
              prepared than after it.
            </p>
          </div>

          <div className="space-y-3">
            <h3 className="text-base font-bold text-main">
              How PNR confirmation prediction works
            </h3>
            <p>
              Trayago&apos;s <strong>PNR prediction</strong> compares your
              current waitlist position against how similar bookings have
              behaved historically on the same train, class, quota, and route,
              factoring in travel date and seasonal demand. The output is a
              probability band rather than a yes or no answer.
            </p>
            <p>
              Treat it as guidance with real limits: unusual demand, group
              cancellations, quota changes, or last-minute operational decisions
              can all push the actual outcome away from the estimate. If the
              probability looks weak, it is worth exploring alternative trains or
              a split journey rather than waiting on the waitlist alone.
            </p>
          </div>

          <div className="space-y-4">
            <h2 className="text-xl font-black text-main">
              PNR status — frequently asked questions
            </h2>
            <dl className="space-y-5">
              {PNR_FAQS.map(({ q, a }) => (
                <div key={q} className="space-y-1.5">
                  <dt className="text-sm font-bold text-main">{q}</dt>
                  <dd className="text-sm text-secondary leading-relaxed">
                    {a}
                  </dd>
                </div>
              ))}
            </dl>
          </div>

          <div className="space-y-3 border-t border-strong pt-8">
            <h3 className="text-base font-bold text-main">Related tools</h3>
            <p>
              Track where your train currently is with{" "}
              <Link
                href="/live"
                className="text-primary font-semibold hover:underline"
              >
                live train running status
              </Link>
              , plan an alternative route from the{" "}
              <Link
                href="/"
                className="text-primary font-semibold hover:underline"
              >
                Trayago train search
              </Link>
              , compare connecting-segment options in the{" "}
              <Link
                href="/split-journey"
                className="text-primary font-semibold hover:underline"
              >
                AI split journey planner
              </Link>
              , find confirmed-seat alternatives with{" "}
              <Link
                href="/ai-waitlist-rescue"
                className="text-primary font-semibold hover:underline"
              >
                AI waitlist rescue
              </Link>
              , set a destination wake-up alarm with the{" "}
              <Link
                href="/tracker"
                className="text-primary font-semibold hover:underline"
              >
                train tracker
              </Link>
              , get status alerts on the{" "}
              <Link
                href="/app"
                className="text-primary font-semibold hover:underline"
              >
                Trayago Android app
              </Link>
              , or read travel guides in{" "}
              <Link
                href="/news"
                className="text-primary font-semibold hover:underline"
              >
                News &amp; Guides
              </Link>
              .
            </p>
            <p className="text-xs text-muted">
              Trayago is an independent travel intelligence platform and is not
              affiliated with, endorsed by, or operated by IRCTC or Indian
              Railways. Ticket booking is completed through official booking
              platforms.
            </p>
          </div>
        </div>
      </section>
    </>
  );
}
