"use client";

import { API_BASE, API_HOST } from "@/lib/api";
import { PnrSocketSubscriptionManager } from "@/lib/pnrSocketClient";
import axios from "axios";
import { AlertTriangle, CheckCircle, Clock, Loader2, Search, ShieldAlert, Ticket, User } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import io from "socket.io-client";
import { QuotaWarningBanner } from "../../components/QuotaWarningBanner";
import { LimitReachedModal } from "../../components/LimitReachedModal";
import { PNRStatusCard } from "../../components/PNRStatusCard";
import { CoachRakeCompositionCard } from "@/components/pnr/CoachRakeCompositionCard";
import { RouteStationsTimelineCard } from "@/components/pnr/RouteStationsTimelineCard";
import { SeatMapModal } from "@/components/pnr/SeatMapModal";
import { CancellationRefundCard } from "@/components/pnr/CancellationRefundCard";
import { TrainStatsCard } from "@/components/pnr/TrainStatsCard";
import { RakeAdvisoryNote } from "@/components/pnr/RakeAdvisoryNote";
import { Button } from "../../components/ui/Button";
import IrctcServiceAdvisoryBanner from "@/components/IrctcServiceAdvisoryBanner";
import MobileVerificationBanner from "@/components/MobileVerificationBanner";
import { useLanguage } from "@/components/LanguageContext";

const getPassengerStatusType = (status: string) => {
  if (!status) return "unknown";

  const s = status.toUpperCase();

  if (s.includes("CAN") || s.includes("MOD") || s.includes("CANCELLED")) return "cancelled";
  if (s.includes("RAC")) return "rac";
  if (s.includes("WL") || s.includes("WAIT") || s.includes("TQWL") || s.includes("PQWL") || s.includes("RLWL") || s.includes("GNWL")) return "waitlist";
  if (s.includes("CNF") || s.includes("CONFIRMED") || (s.includes("-") && !s.includes("WL")) || /[A-Z]+\d+/.test(s)) return "confirmed";

  return "unknown";
};
export default function PNRPage() {
  const { t } = useLanguage();
  const [pnr, setPnr] = useState("");
  const [loading, setLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [pnrData, setPnrData] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [showLimitModal, setShowLimitModal] = useState(false);
  const [quotaStatus, setQuotaStatus] = useState<any>(null);
  const [showSeatMap, setShowSeatMap] = useState(false);
  const [selectedSeatPax, setSelectedSeatPax] = useState<any>(null);

  const fetchQuotaStatus = async () => {
    try {
      const deviceId = localStorage.getItem("deviceId") || "";
      const betaCode = localStorage.getItem("betaCode") || "";
      const { buildAuthHeaders } = await import("@/lib/authHeaders");
      const { ensureAccessToken } = await import("@/lib/sessionBootstrap");
      await ensureAccessToken();
      const res = await axios.get(`${API_BASE}/auth/quota-status`, {
        params: { deviceId, betaCode },
        headers: buildAuthHeaders(),
      });
      if (res.data.success) {
        setQuotaStatus(res.data.data);
      }
    } catch (e) {}
  };

  useEffect(() => {
    fetchQuotaStatus();
  }, []);

  const socketRef = useRef<any>(null);
  const subscriptionRef = useRef<PnrSocketSubscriptionManager | null>(null);

  // Initialize socket + P0-009 subscription manager (no stale pnr closure)
  useEffect(() => {
    const socket = io(API_HOST, {
      transports: ['websocket'],
      reconnection: true,
      reconnectionAttempts: 5,
      reconnectionDelay: 1000,
    });
    socketRef.current = socket;

    const manager = new PnrSocketSubscriptionManager(
      () => socketRef.current,
      {
        onPnrUpdate: (data: any) => {
          setPnrData((prevData: any) => {
            if (!data) return prevData;
            const raw = data.data || data;
            const train_name = raw.train_name || raw.trainName || raw.train?.name || prevData?.train_name;
            const train_no = raw.train_no || raw.train_number || raw.trainNumber || raw.train?.number || prevData?.train_no;
            const journey_date = raw.journey_date || raw.journeyDate || raw.journey?.dateOfJourney || raw.boardingDay || prevData?.journey_date;
            const source = raw.source || raw.source_name || raw.source_station || raw.journey?.source?.name || raw.journey?.source?.code || prevData?.source;
            const destination = raw.destination || raw.destination_name || raw.destination_station || raw.journey?.destination?.name || raw.journey?.destination?.code || prevData?.destination;
            const chart_status = raw.chart_status || raw.chartStatus || raw.chart?.status || prevData?.chart_status;
            const rawPassengers = raw.passengers || raw.passenger_status || prevData?.passengers || [];

            const mapped = rawPassengers.map((p: any, idx: number) => {
              const currentStatus = p.currentStatus || p.current_status || p.current?.details || p.current?.status || "";
              const bookingStatus = p.bookingStatus || p.booking_status || p.booking?.details || p.booking?.status || "";
              const statusRaw = currentStatus || bookingStatus || "Unknown";
              const type = getPassengerStatusType(statusRaw);

              let displayStatus = statusRaw;
              let suggestion = "";
              if (type === "cancelled") {
                displayStatus = "CANCELLED";
                suggestion = "❌ Ticket cancelled. Book alternative train immediately.";
              } else if (type === "waitlist" || type === "rac") {
                displayStatus = "WAITLIST / RAC";
                suggestion = "⚠️ Waitlist. Check confirmation probability or try another train.";
              } else if (type === "confirmed") {
                displayStatus = "CONFIRMED";
                suggestion = "✅ Ticket confirmed. You're good to travel.";
              }

              return {
                ...p,
                name: p.passenger || p.name || p.serialNumber || `Passenger ${idx + 1}`,
                booking_status: bookingStatus,
                current_status: currentStatus,
                seat: p.seat_number || p.seat || p.current?.berthNo || p.booking?.berthNo || bookingStatus,
                status: statusRaw,
                displayStatus,
                aiAdvice: suggestion
              };
            });

            return {
              ...prevData,
              ...raw,
              pnr: raw.pnr || prevData?.pnr,
              train_name,
              train_no,
              journey_date,
              source,
              destination,
              chart_status,
              passengers: rawPassengers,
              mappedPassengers: mapped,
            };
          });
        },
        onAutoRefreshStopped: (payload) => {
          alert(payload.message || 'Chart has been prepared. Auto-refresh disabled.');
        },
      }
    );
    subscriptionRef.current = manager;

    const detach = manager.attach(socket);

    return () => {
      manager.unsubscribe();
      detach();
      socket.disconnect();
      socketRef.current = null;
      subscriptionRef.current = null;
    };
  }, []);

  // Subscribe to PNR room when result is loaded
  useEffect(() => {
    const manager = subscriptionRef.current;
    if (!manager) return;

    const activePnr =
      pnrData?.pnr != null
        ? String(pnrData.pnr)
        : pnr.length === 10
          ? pnr
          : null;
    manager.setActivePnr(activePnr);

    if (activePnr) {
      manager.subscribe(activePnr);
    }

    return () => {
      if (activePnr) {
        manager.unsubscribe(activePnr);
      }
    };
  }, [pnrData, pnr]);

  const handleTrack = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!pnr || pnr.length !== 10) {
      setError("Please enter a valid 10-digit PNR number.");
      return;
    }

    setLoading(true);
    setHasSearched(true);
    setError(null);
    setPnrData(null);

    try {
      const { buildAuthHeaders } = await import("@/lib/authHeaders");
      const res = await axios.get(`${API_BASE}/pnr/${pnr}`, { headers: buildAuthHeaders() });

      if (res.data && res.data.success !== false) {
        const raw = res.data?.data || res.data;
        const train_name = raw.train_name || raw.trainName || raw.train?.name || "Train Details";
        const train_no = raw.train_no || raw.train_number || raw.trainNumber || raw.train?.number || "";
        const journey_date = raw.journey_date || raw.journeyDate || raw.journey?.dateOfJourney || raw.boardingDay || "";
        const source = raw.source || raw.source_name || raw.source_station || raw.sourceStation || raw.journey?.source?.name || raw.journey?.source?.code || "";
        const destination = raw.destination || raw.destination_name || raw.destination_station || raw.destinationStation || raw.journey?.destination?.name || raw.journey?.destination?.code || "";
        const chart_status = raw.chart_status || raw.chartStatus || raw.chart?.status || "Not Prepared";
        const passengers = raw.passengers || raw.passenger_status || [];

        const mapped = passengers.map((p: any, idx: number) => {
          const currentStatus = p.currentStatus || p.current_status || p.current?.details || p.current?.status || "";
          const bookingStatus = p.bookingStatus || p.booking_status || p.booking?.details || p.booking?.status || "";
          const statusRaw = currentStatus || bookingStatus || "Unknown";
          
          const type = getPassengerStatusType(statusRaw);

          let displayStatus = statusRaw;
          let suggestion = "";

          if (type === "cancelled") {
            displayStatus = "CANCELLED";
            suggestion = "❌ Ticket cancelled. Book alternative train immediately.";
          } else if (type === "waitlist" || type === "rac") {
            displayStatus = "WAITLIST / RAC";
            suggestion = "⚠️ Waitlist. Check confirmation probability or try another train.";
          } else if (type === "confirmed") {
            displayStatus = "CONFIRMED";
            suggestion = "✅ Ticket confirmed. You're good to travel.";
          }

          return {
            ...p,
            name: p.passenger || p.name || p.serialNumber || `Passenger ${idx + 1}`,
            booking_status: bookingStatus,
            current_status: currentStatus,
            seat: p.seat_number || p.seat || p.current?.berthNo || p.booking?.berthNo || bookingStatus,
            status: statusRaw,
            displayStatus,
            passenger: p.passenger,
            aiAdvice: suggestion
          };
        });

        setPnrData({
          ...raw,
          pnr: raw.pnr || pnr,
          train_name,
          train_no,
          journey_date,
          source,
          destination,
          chart_status,
          passengers,
          mappedPassengers: mapped
        });
      } else {
        setError(res.data.error || "Failed to fetch PNR status. Invalid PNR or server issue.");
      }
    } catch (err: any) {
      if (err.response?.status === 403 || err.response?.data?.error === 'limit_exceeded') {
        setShowLimitModal(true);
      } else {
        setError(err.response?.data?.error || err.message || "An error occurred fetching PNR status.");
      }
    } finally {
      setLoading(false);
      fetchQuotaStatus();
    }
  };

  const getStatusColor = (status: string) => {
    const type = getPassengerStatusType(status);
    if (type === "confirmed") return "text-emerald-700 dark:text-emerald-400 bg-emerald-500/10 border-emerald-500/20";
    if (type === "rac") return "text-blue-700 dark:text-blue-400 bg-blue-500/10 border-blue-500/20";
    if (type === "waitlist") return "text-amber-700 dark:text-amber-400 bg-amber-500/10 border-amber-500/20";
    if (type === "cancelled") return "text-rose-700 dark:text-rose-400 bg-rose-500/10 border-rose-500/20";
    return "text-muted bg-slate-500/10 border-slate-500/20";
  };

  const getStatusIcon = (status: string) => {
    const type = getPassengerStatusType(status);
    if (type === "confirmed") return <CheckCircle className="w-4 h-4" />;
    if (type === "rac" || type === "waitlist") return <Clock className="w-4 h-4" />;
    if (type === "cancelled") return <AlertTriangle className="w-4 h-4" />;
    return <User className="w-4 h-4" />;
  };


  const goToSearchWithContext = () => {
    if (!pnrData) {
      window.location.href = "/search";
      return;
    }

    // Attempt to extract source and destination from PNR. Some APIs provide boarding point or source_station.
    const sourceCode = pnrData.source_station || pnrData.sourceStation || pnrData.board_station || pnrData.boardingPoint || "";
    const destCode = pnrData.destination_station || pnrData.destinationStation || pnrData.resv_upto_station || pnrData.destinationPoint || "";

    // Format date properly (assuming YYYY-MM-DD or DD-MM-YYYY depending on PNR, we will pass as is and let Search handle it)
    let parsedDate = pnrData.journey_date || pnrData.journeyDate || "";

    const data = {
      trainName: pnrData.train_name || pnrData.trainName,
      trainNumber: pnrData.train_number || pnrData.trainNumber,
      source: sourceCode,
      destination: destCode,
      date: parsedDate
    };

    localStorage.setItem("pnrContext", JSON.stringify(data));
    window.location.href = "/search";
  };

  return (
    <div className="w-full flex-1 flex flex-col p-4 md:p-8 selection:bg-rose-500/30">
      <div className="max-w-4xl mx-auto w-full space-y-8 pb-12">

        <QuotaWarningBanner 
          status={quotaStatus} 
          onUpgradeClick={() => setShowLimitModal(true)} 
        />

        <MobileVerificationBanner />

        <IrctcServiceAdvisoryBanner variant="inline" />

        {/* Header & Search Form */}
        <div className="relative bg-card border border-strong rounded-2xl p-6 shadow-card">
          <div className="flex items-center gap-3 mb-6">
            <div className="p-3 bg-blue-500/10 text-blue-600 dark:text-blue-400 rounded-xl">
              <Ticket className="w-6 h-6" />
            </div>
            <div>
              <h1 className="text-2xl font-bold tracking-tight text-main">{t('pnr_status_title')}</h1>
              <p className="text-sm text-secondary">{t('pnr_status_subtitle')}</p>
            </div>
          </div>

          <form onSubmit={handleTrack} className="flex flex-col md:flex-row gap-4">
            <div className="flex-1 space-y-2">
              <div className="flex items-center justify-between pl-1">
                <label className="text-xs font-black text-muted uppercase tracking-wider flex items-center gap-1.5">
                  <span>{t('pnr_input_label')}</span>
                </label>
                <div className="text-[11px] font-mono">
                  {pnr.length === 0 ? (
                    <button
                      type="button"
                      onClick={async () => {
                        try {
                          if (typeof navigator !== 'undefined' && navigator.clipboard?.readText) {
                            const text = await navigator.clipboard.readText();
                            const digits = text.replace(/\D/g, '').slice(0, 10);
                            if (digits) setPnr(digits);
                          }
                        } catch {}
                      }}
                      className="inline-flex items-center gap-1 text-primary hover:underline cursor-pointer font-sans text-xs font-semibold"
                    >
                      <Ticket size={12} />
                      <span>{t('pnr_paste')}</span>
                    </button>
                  ) : pnr.length === 10 ? (
                    <span className="inline-flex items-center gap-1 text-emerald-500 font-bold text-xs">
                      <CheckCircle className="w-3.5 h-3.5" />
                      <span>{t('pnr_ready')}</span>
                    </span>
                  ) : (
                    <span className="text-muted font-bold">
                      <strong className="text-amber-500">{pnr.length}</strong> / 10 digits
                    </span>
                  )}
                </div>
              </div>

              <div className="relative flex items-center">
                <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none">
                  <div className="w-8 h-8 rounded-xl bg-blue-500/10 border border-blue-500/20 flex items-center justify-center text-blue-500">
                    <Ticket className="w-4 h-4" />
                  </div>
                </div>
                <input
                  type="text"
                  maxLength={10}
                  inputMode="numeric"
                  pattern="[0-9]*"
                  placeholder={t('pnr_placeholder_input')}
                  value={pnr}
                  onChange={(e) => setPnr(e.target.value.replace(/\D/g, ''))}
                  className="w-full bg-input border border-strong rounded-2xl pl-14 pr-12 py-3.5 text-base sm:text-lg font-bold tracking-[0.2em] font-mono focus:outline-none focus:ring-2 focus:ring-primary/30 focus:border-primary transition-all placeholder:text-muted/60 placeholder:tracking-normal placeholder:font-sans placeholder:text-sm text-main h-14 shadow-inner"
                  required
                />
                {pnr.length > 0 && (
                  <button
                    type="button"
                    onClick={() => setPnr('')}
                    className="absolute right-3.5 p-1.5 rounded-xl bg-card border border-subtle text-muted hover:text-main transition-colors cursor-pointer"
                    title="Clear PNR"
                  >
                    <AlertTriangle className="sr-only" />
                    <span className="text-xs font-bold font-mono px-1">✕</span>
                  </button>
                )}
              </div>
            </div>

            <div className="flex items-end">
              <Button
                type="submit"
                disabled={loading || pnr.length !== 10}
                variant="primary"
                size="lg"
                className="w-full md:w-auto h-14 px-8 shadow-md hover:shadow-glow-primary border border-primary/25 font-black text-sm tracking-wide flex items-center justify-center gap-2 transition-all hover:-translate-y-0.5 active:translate-y-0 rounded-2xl cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {loading ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin shrink-0" />
                    <span>{t('checking')}</span>
                  </>
                ) : (
                  <>
                    <Search className="w-4 h-4 shrink-0 mr-1" />
                    <span>{t('check_status')}</span>
                  </>
                )}
              </Button>
            </div>
          </form>
          </div>

        {error && (
          <div className="p-4 bg-rose-500/10 border border-rose-500/30 rounded-xl text-rose-400 text-sm flex items-center gap-3 shadow-lg shadow-rose-500/10 animate-in fade-in zoom-in duration-300">
            <ShieldAlert className="w-5 h-5 flex-shrink-0" />
            <p>{error}</p>
          </div>
        )}

        {/* Loading State with Rail Transit Telemetry */}
        {loading && (
          <div className="rounded-3xl p-6 sm:p-8 bg-card border border-strong relative overflow-hidden shadow-card text-center select-none space-y-4">
            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-blue-500/5 to-transparent animate-[shimmer_2s_infinite]" />
            <div className="inline-flex items-center gap-2 px-3.5 py-1 bg-input/80 border border-subtle rounded-full text-xs font-semibold text-muted shadow-xs">
              <Loader2 className="w-3.5 h-3.5 text-blue-500 animate-spin shrink-0" />
              <span className="font-mono font-bold text-blue-600 dark:text-blue-400">PNR #{pnr}</span>
              <span className="text-muted/40">•</span>
              <span>Connecting to IRCTC PNR Gateway</span>
            </div>

            <div className="w-48 max-w-full mx-auto h-1.5 bg-input rounded-full overflow-hidden border border-subtle/50">
              <div className="h-full bg-gradient-to-r from-cyan-400 via-blue-500 to-indigo-500 rounded-full animate-pulse" style={{ width: '70%' }} />
            </div>

            <p className="text-xs text-muted max-w-sm mx-auto">
              Decrypting chart status, passenger waitlist movement, and confirmation probability...
            </p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-3 pt-2">
              <div className="h-16 bg-input/60 rounded-2xl border border-subtle animate-pulse" />
              <div className="h-16 bg-input/60 rounded-2xl border border-subtle animate-pulse" />
            </div>
          </div>
        )}

        {/* Results */}
        {!loading && hasSearched && pnrData && (
          <>
            <PNRStatusCard 
              data={{
                pnr: pnr,
                train_name: pnrData.train_name || pnrData.trainName || pnrData.train?.name || "Train Details",
                train_no: pnrData.train_no || pnrData.train_number || pnrData.trainNumber || pnrData.train?.number || "",
                journey_date: pnrData.journey_date || pnrData.journeyDate || pnrData.journey?.dateOfJourney || pnrData.boardingDay || "",
                departure_time: pnrData.departure_time || pnrData.departureTime || pnrData.journey?.departureTime || undefined,
                arrival_time: pnrData.arrival_time || undefined,
                source_code: pnrData.source_code || '',
                destination_code: pnrData.destination_code || '',
                distance: pnrData.distance || '',
                duration: pnrData.duration || '',
                source: pnrData.source || pnrData.source_name || pnrData.source_station || pnrData.sourceStation || pnrData.journey?.source?.name || pnrData.journey?.source?.code || "",
                destination: pnrData.destination || pnrData.destination_name || pnrData.destination_station || pnrData.destinationStation || pnrData.journey?.destination?.name || pnrData.journey?.destination?.code || "",
                passengers: (pnrData.passengers || pnrData.passenger_status || []).map((p: any, idx: number) => ({
                  name: p.passenger || p.name || p.serialNumber || `Passenger ${idx + 1}`,
                  booking_status: p.booking_status || p.bookingStatus || p.booking?.details || p.booking?.status || "Unknown",
                  current_status: p.current_status || p.currentStatus || p.current?.details || p.current?.status || "Unknown"
                })),
                prediction: pnrData.prediction ? {
                  probability: pnrData.prediction.probability || pnrData.prediction.confirmationProbability || "",
                  text: pnrData.prediction.text || pnrData.prediction.confirmationLabel || "Unknown",
                  advice: pnrData.prediction.advice || "",
                  explanation: pnrData.prediction.explanation || "",
                  confidence_label: pnrData.prediction.confidence_label || "",
                  worst_pos: pnrData.prediction.worst_pos ?? pnrData.prediction.worstPosition ?? 0,
                  booking_pos: pnrData.prediction.booking_pos ?? pnrData.prediction.bookingPosition,
                  prediction_available: pnrData.prediction.prediction_available,
                  prediction_source: pnrData.prediction.prediction_source || pnrData.prediction.predictionSource,
                  is_pro: pnrData.prediction.is_pro ?? pnrData.is_pro
                } : undefined,
                is_pro: pnrData.is_pro ?? pnrData.prediction?.is_pro,
                chart_status: pnrData.chart_status || pnrData.chartStatus || pnrData.chart?.status || "Not Prepared",
                boarding_station: pnrData.boarding_station || pnrData.boardingStation || pnrData.journey?.boardingPoint?.name || "",
                twitter_complaint_url: pnrData.twitter_complaint_url
              }} 
              onViewSeatMap={() => {
                setShowSeatMap(true);
              }}
            />

            {/* Estimated Cancellation Refund Card (Matching RailCore Order & Benchmark) */}
            <div className="pt-4">
              <CancellationRefundCard
                pnr={pnr}
                journeyDate={pnrData.journey_date || pnrData.journeyDate || pnrData.journey?.dateOfJourney || "9 Oct 2026"}
                fare={pnrData.fare || pnrData.ticket_fare || pnrData.ticketFare || 645}
                travelClass={pnrData.class || pnrData.travel_class || pnrData.journeyClass || "SL"}
                quota={pnrData.quota || pnrData.quotaCode || "PT"}
                passengers={pnrData.passengers || pnrData.passenger_status || []}
                chartStatus={pnrData.chart_status || pnrData.chartStatus}
              />
            </div>

            {/* Coach Rake Composition Card, Route Timeline, Specs & Advisory */}
            {(() => {
              const passengers = pnrData.passengers || pnrData.passenger_status || [];
              const firstPax = selectedSeatPax || passengers[0];
              const cur = firstPax?.current_status || firstPax?.currentStatus || firstPax?.current?.details || '';
              const parts = cur.split('/').map((s: string) => s.trim()).filter(Boolean);
              const bParts = ((firstPax as any)?.booking_status || '').split('/').map((s: string) => s.trim()).filter(Boolean);
              const coach = firstPax?.coach || (parts.length >= 2 && !/^\d+$/.test(parts[1]) ? parts[1] : (bParts.length >= 2 && !/^\d+$/.test(bParts[1]) ? bParts[1] : undefined));

              const extractTimeFromDate = (str?: string) => {
                if (!str) return undefined;
                const match = str.match(/\b(\d{1,2}:\d{2})(?::\d{2})?\s*(AM|PM|am|pm)?\b/);
                if (match) {
                  return `${match[1]} ${match[2] || ''}`.trim();
                }
                return undefined;
              };

              const cleanDateStr = (str?: string) => {
                if (!str) return '';
                const d = new Date(str);
                if (!isNaN(d.getTime())) {
                  return d.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' });
                }
                return str.split(/\d{1,2}:\d{2}/)[0].trim() || str;
              };

              return (
                <div className="space-y-6 pt-4">
                  <CoachRakeCompositionCard
                    trainNo={pnrData.train_no || pnrData.train_number || ''}
                    trainName={pnrData.train_name || ''}
                    userCoach={coach}
                    userClass={pnrData.class || pnrData.travel_class || "SL"}
                    onOpenSeatMap={() => setShowSeatMap(true)}
                  />

                  <RouteStationsTimelineCard
                    sourceStation={pnrData.source || pnrData.source_name || "Boarding Station"}
                    destinationStation={pnrData.destination || pnrData.destination_name || "Destination Station"}
                    sourceCode={pnrData.source_code || (pnrData.source?.slice(0, 4) || 'SRC')}
                    destinationCode={pnrData.destination_code || (pnrData.destination?.slice(0, 4) || 'DST')}
                    departureTime={pnrData.departure_time || extractTimeFromDate(pnrData.journey_date)}
                    arrivalTime={pnrData.arrival_time || undefined}
                    journeyDate={cleanDateStr(pnrData.journey_date || pnrData.journeyDate || '')}
                    arrivalDate={pnrData.arrival_date ? cleanDateStr(pnrData.arrival_date) : cleanDateStr(pnrData.journey_date || pnrData.journeyDate || '')}
                    boardingPlatform={pnrData.platform || undefined}
                    destinationPlatform={undefined}
                    distanceKm={pnrData.distance || undefined}
                    travelDuration={pnrData.duration || undefined}
                    scheduledStops={(pnrData as any).stops_count ? `${(pnrData as any).stops_count} stops` : undefined}
                    passThroughCount={(pnrData as any).pass_through_count ? `${(pnrData as any).pass_through_count} stations` : undefined}
                    fullRunDescription={pnrData.full_run_description || `Train #${pnrData.train_no} ${pnrData.train_name}`}
                  />

                  <TrainStatsCard
                    trainNo={pnrData.train_no || pnrData.train_number || ''}
                    trainName={pnrData.train_name || ''}
                    source={pnrData.source || pnrData.source_name || ''}
                    destination={pnrData.destination || pnrData.destination_name || ''}
                    platform={pnrData.platform || undefined}
                    avgSpeed={(pnrData as any).avg_speed || undefined}
                    maxSpeed={(pnrData as any).max_speed || undefined}
                    distanceKm={pnrData.distance || undefined}
                    duration={pnrData.duration || undefined}
                    rakeType={(pnrData as any).rake_type || undefined}
                    inauguralYear={(pnrData as any).inaugural_year || undefined}
                  />

                  <RakeAdvisoryNote />
                </div>
              );
            })()}
          </>
        )}
      </div>

      {/* Interactive Seat Map Modal */}
      {(() => {
        const passengers = pnrData?.passengers || pnrData?.passenger_status || [];
        const firstPax = selectedSeatPax || passengers[0];
        const cur = firstPax?.current_status || firstPax?.currentStatus || firstPax?.current?.details || '';
        const parts = cur.split('/').map((s: string) => s.trim());
        const coach = parts.length >= 3 ? parts[1] : undefined;
        const berth = parts.length >= 3 ? parts[2] : undefined;
        const bType = parts.length >= 4 ? parts[3].toUpperCase() : undefined;
        const bDesc = bType === 'LB' ? 'Lower Berth' : bType === 'MB' ? 'Middle Berth' : bType === 'UB' ? 'Upper Berth' : bType === 'SL' ? 'Side Lower' : bType === 'SU' ? 'Side Upper' : bType;

        return (
          <SeatMapModal
            isOpen={showSeatMap}
            onClose={() => setShowSeatMap(false)}
            coach={coach}
            berthNumber={berth}
            berthType={bDesc}
            passengerName={firstPax?.name || firstPax?.passenger}
            travelClass={pnrData?.class || pnrData?.travel_class}
            trainNo={pnrData?.train_no || pnrData?.train_number}
            trainName={pnrData?.train_name}
          />
        );
      })()}
      <LimitReachedModal 
        isOpen={showLimitModal} 
        onClose={() => {
          setShowLimitModal(false);
          fetchQuotaStatus();
        }} 
        onRefresh={() => {
          setError(null);
          handleTrack({ preventDefault: () => {} } as any);
        }} 
      />
    </div>
  );
}
